extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var platform := find_by_name(main, "MovingPlatform") as AnimatableBody2D
	if not check("platform", platform != null, "La scena principale deve contenere il nodo MovingPlatform"):
		return
	var start_pos := platform.global_position
	await wait_physics_frames(30)
	var end_pos := platform.global_position
	check("platform_moves", start_pos.distance_to(end_pos) > 5.0, "La piattaforma mobile deve spostarsi nel tempo (iniziale %s, attuale %s)" % [start_pos, end_pos])

